'use client';

import * as React from 'react';
import { Checkbox as BaseCheckbox } from '@base-ui/react/checkbox';
import './checkbox.css';

/* ─────────────────────────────────────────────────────────
 * CHECKBOX, the dimple (the reference design's .dimple) on Base UI Checkbox
 *
 *   rest     a recessed well in the margin
 *   hover    the well darkens a step
 *   on       a dark pressed key; the white tick draws on (ease-out, 220 ms after a 40 ms beat)
 *   doing    a half-filled green square (announced as mixed)
 *   ghost    a hollow ring: a task that was inferred, not written; green ring on hover
 *   row      size="row": 14 with radius 5 and a smaller tick, in a list row (in flow, not the margin)
 * Its look is the checkbox recipe (tokens.json recipes.checkbox → --mu-r-checkbox-*).
 * ───────────────────────────────────────────────────────── */

export interface CheckboxProps extends Omit<BaseCheckbox.Root.Props, 'className' | 'indeterminate'> {
  /** The task is in progress: a half-filled green square (announced as mixed). */
  doing?: boolean;
  /** A task the recognizer inferred and nobody wrote: the hollow ghost dimple, hanging in the margin. */
  ghost?: boolean;
  /** margin (16, the default) beside a block; row (14) at the start of a list row. */
  size?: 'margin' | 'row';
  className?: string;
}

/**
 * A task's checkbox: a 16 pt well in the margin. Checked, it turns dark and the tick draws on.
 * Ticking it is a person's action: the host writes `[x]` into the text, with Undo.
 */
export const Checkbox = React.forwardRef<HTMLButtonElement, CheckboxProps>(function Checkbox({ doing, ghost, size, className, ...props }, ref) {
  // The slot carries placement (the margin at −25): Base UI renders a hidden form input beside the
  // checkbox, and the slot keeps both out of the line's flow.
  return (
    <span className={className ? `mu-dimple-slot ${className}` : 'mu-dimple-slot'}>
      <BaseCheckbox.Root ref={ref} indeterminate={doing && !props.checked ? true : undefined} data-ghost={ghost ? '' : undefined} data-size={size === 'row' ? 'row' : undefined} className="mu-dimple" {...props}>
        <BaseCheckbox.Indicator render={(p, state) => (state.checked ? <span {...p} className="mu-dimple-tick" /> : <span {...p} hidden />)} />
      </BaseCheckbox.Root>
    </span>
  );
});

/** The earlier name (kept for existing hosts). */
export const Dimple = Checkbox;
export type DimpleProps = CheckboxProps;

@import "../tokens.css";

/* Checkbox, the dimple (the reference design's .dimple): a task's checkbox, a well in the margin. Its look is the checkbox recipe. */
.mu-dimple-slot { display: inline-flex; width: max-content; height: max-content; line-height: 0; }
.mu-dimple {
  position: relative;
  box-sizing: border-box;
  display: inline-block;
  width: var(--mu-r-checkbox-self-size);
  height: var(--mu-r-checkbox-self-size);
  padding: var(--mu-zero);
  border: 0;
  border-radius: var(--mu-r-checkbox-self-radius);
  cursor: pointer;
  background: var(--mu-r-checkbox-self-background);
  box-shadow: var(--mu-r-checkbox-self-shadow);
  transition: background var(--mu-r-checkbox-self-fade), box-shadow var(--mu-r-checkbox-self-fade);
  -webkit-tap-highlight-color: transparent;
}
.mu-dimple:hover:not([data-checked]):not([data-ghost]) { background: var(--mu-r-checkbox-self-hover-background); }
.mu-dimple[data-checked] { background: var(--mu-r-checkbox-self-on-background); box-shadow: var(--mu-r-checkbox-self-on-shadow); }
.mu-dimple:focus-visible { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-focus-offset); }
.mu-dimple[data-disabled] { opacity: var(--mu-r-checkbox-self-disabled); cursor: default; }
/* The tick draws on with an ease-out after a short beat: not sprung (DS-21). */
.mu-dimple-tick {
  position: absolute;
  left: var(--mu-r-checkbox-tick-x);
  top: var(--mu-r-checkbox-tick-y);
  width: var(--mu-r-checkbox-tick-w);
  height: var(--mu-r-checkbox-tick-h);
  border: solid var(--mu-r-checkbox-tick-color);
  border-width: 0 var(--mu-r-checkbox-tick-stroke) var(--mu-r-checkbox-tick-stroke) 0;
  transform: rotate(var(--mu-r-checkbox-tick-rotate));
  animation: mu-dimple-tick var(--mu-r-checkbox-tick-draw) var(--mu-r-checkbox-tick-delay) var(--mu-ease-slide) both;
}
@keyframes mu-dimple-tick { from { clip-path: inset(0 100% 100% 0); } to { clip-path: inset(0 0 0 0); } }
@media (prefers-reduced-motion: reduce) { .mu-dimple-tick { animation: none; } }
[data-mu-motion="reduce"] .mu-dimple-tick { animation: none; }
/* Row: the smaller dimple at the start of a list row. */
.mu-dimple[data-size="row"]:not([data-ghost]) { width: var(--mu-r-checkbox-row-size); height: var(--mu-r-checkbox-row-size); border-radius: var(--mu-r-checkbox-row-radius); }
.mu-dimple[data-size="row"] .mu-dimple-tick { left: var(--mu-r-checkbox-row-tick-x); top: var(--mu-r-checkbox-row-tick-y); width: var(--mu-r-checkbox-row-tick-w); height: var(--mu-r-checkbox-row-tick-h); }
/* Doing: a half-filled green square. */
.mu-dimple[data-indeterminate]::before {
  content: "";
  position: absolute;
  inset: var(--mu-r-checkbox-doing-inset);
  border-radius: var(--mu-r-checkbox-doing-radius);
  background: var(--mu-r-checkbox-doing-background);
  opacity: var(--mu-r-checkbox-doing-opacity);
}
/* Ghost: an inferred task, not written. Hangs in the margin; the band grows left instead of the words moving. */
.mu-dimple[data-ghost] {
  width: var(--mu-r-checkbox-ghost-size);
  height: var(--mu-r-checkbox-ghost-size);
  border-radius: var(--mu-r-checkbox-ghost-radius);
  background: var(--mu-r-checkbox-self-ghost-background);
  box-shadow: var(--mu-r-checkbox-self-ghost-shadow);
}
.mu-dimple[data-ghost]:hover { box-shadow: var(--mu-r-checkbox-self-ghost-hover-shadow); }
